mod base ; mod cdlout ; mod cli ; mod elab ; mod folder ; mod process ; mod tasks ; mod workflow ; use clap :: { crate_name , crate_version , Parser } ; # [derive (Parser)] # [clap (version = crate_version ! () , author = crate_name ! ())] pub struct Opts { # [doc = " Project directory where all settings, input and output will be stored"] pub project_directory : Option < String > , # [doc = " Create project directory structure if it's not there,"] # [doc = " write config files if they've been modified"] # [clap (short , long)] pub write_config : bool , # [doc = " main SPICE/CDL input file"] # [clap (short , long)] pub file : Option < String > , # [doc = " top SUBCKT (will be autodetected if absent)"] # [clap (short , long)] pub top : Option < String > , } fn get_top < C : spircer :: CaseBehavior > (circuit : & base :: CircuitInner < C >) -> (Option < usize > , String) { let top_id = & circuit . subckt_idents [circuit . top] . full_id ; let color = unsafe { spircer :: GLOBALS . colors } ; unsafe { spircer :: GLOBALS . colors = false } let name = top_id . scope . to_string () ; unsafe { spircer :: GLOBALS . colors = color } (Some (top_id . nb_pins) , name) } fn main () -> anyhow :: Result < () > { let opts : Opts = Opts :: parse () ; let folder = folder :: Folder :: new (& opts) ? ; let mut parser_opts = folder . get_parser_opts () ? ; pretty_env_logger :: init () ; unsafe { spircer :: GLOBALS . colors = atty :: is (atty :: Stream :: Stdout) } ; if let Some (top) = & opts . top { parser_opts . top = Some ((None , top . clone ())) ; } for (key , value) in std :: env :: vars () { match (key . as_str () , value . as_str ()) { ("COLOR" , _) => unsafe { spircer :: GLOBALS . colors = true } , ("NO_COLOR" , _) | ("TERM" , "dumb") => unsafe { spircer :: GLOBALS . colors = false } , _ => () , } } workflow :: gogogo (opts , folder , parser_opts) }